corrected_code:
const { createProxyMiddleware } = require('http-proxy-middleware');

app.use('/analytics/organizations/:orgId/query', verifyToken, (req, res, next) => {
  if (req.user.organizationId !== req.params.orgId) {
    return res.status(403).json({ error: 'Forbidden: unauthorized organization analytics scope' });
  }
  createProxyMiddleware({
    target: process.env.CLICKHOUSE_QUERY_PROXY_URL,
    changeOrigin: true,
    pathRewrite: {
      ['^/analytics/organizations/' + req.params.orgId]: `/clickhouse/tenant/${req.params.orgId}`
    }
  })(req, res, next);
});
